import sys; sys.path.insert(0,'.')
from cvlib import folds
d=np.load('base_reads.npz'); y=d['y']; R=np.load('reserved.npy')
keep=np.setdiff1d(np.arange(768),R)
M={j:d[f'mean_hidden_L{j}'][:,keep] for j in range(13)}
def z(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def kcv(K, y, lams, seeds=(0,1,2)):
    Y=np.eye(8)[y]; out={}
    for lam in lams:
        a=[]
        for s in seeds:
            f=folds(y,5,s); S=np.zeros((len(y),8))
            for i in range(5):
                tr=f!=i; te=f==i
                Ktr=K[np.ix_(tr,tr)]; Yc=Y[tr]-Y[tr].mean(0)
                A=np.linalg.solve(Ktr+lam*np.eye(tr.sum()), Yc)
                S[te]=K[np.ix_(te,tr)]@A
            a.append((S.argmax(1)==y).mean())
        out[lam]=round(100*np.mean(a),2)
    return out
def quad(X):
    Z=z(X); Z/=np.linalg.norm(Z,axis=1,keepdims=True); Cc=Z@Z.T; return Cc+0.5*Cc**2
def rbf(X,g):
    Z=z(X)/np.sqrt(X.shape[1]); sq=(Z**2).sum(1); D=sq[:,None]+sq[None]-2*Z@Z.T; return np.exp(-g*D)
def lin(X): Z=z(X)/np.sqrt(X.shape[1]); return Z@Z.T
for j in [7,8,9,10]:
    for name,K in [('quad',quad(M[j])),('quad+linM2',quad(M[j])+lin(M[2])),('rbf.35+linM2',rbf(M[j],.35)+lin(M[2])),('rbf.35+linM2+linM6',rbf(M[j],.35)+lin(M[2])+lin(M[6]))]:
        print(j,name,kcv(K,y,(3e-3,1e-2,3e-2)))
